{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 This is a ReaScript for REAPER that provides tools for creating legato effects in MIDI. It extends MIDI notes to create legato effects, detects and handles note overlays, and fills gaps between notes.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 The tool provides a user interface for adjusting settings and applying legato effects to selected MIDI notes in the MIDI editor.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 This is a ReaScript for REAPER that provides tools for cleaning up MIDI CC data. It removes redundant control change events and smooths selected CCs in the MIDI editor.\par}
{\pard \ql \f0 \sa180 \li0 \fi0 The tool provides a user interface for adjusting settings and applying CC cleanup operations to selected MIDI CCs in the MIDI editor.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 This is a quick heal script that heals note overlays in selected MIDI notes without any UI. It adjusts notes so that same-pitch notes don't overlap.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 This is a quick legato script that applies legato to selected MIDI notes without any UI. It extends MIDI notes to create legato effects with a default legato amount of 50ms, no humanization, and no boundary constraints.\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 This file contains common functions shared between the main Legato Tool and the quick scripts (Quick-Legato, Quick-Heal, etc.).\par}
}

{\rtf1\ansi\deff0{\fonttbl{\f0 \fswiss Helvetica;}{\f1 \fmodern Courier;}}
{\colortbl;\red255\green0\blue0;\red0\green0\blue255;}
\widowctrl\hyphauto

{\pard \ql \f0 \sa180 \li0 \fi0 This script save/restore the state of all FX inserts. It stores the original -- state in track metadata.\par}
}
